    kH, RH = 1.667, 2.0769; sH = reg('cdexit', dict(P0=1000.0, T0=500.0, k=kH, R=RH, mdot=0.25, Pe=100.0), 'As', 0.25 / mdot_choked(1.0, 1000.0, 500.0, kH, RH) * 1e4, 1e-9, '17-135 throat cm2')
