    prn('Cengel 17-135 throat area (cm2)', 3.51, sH, 2e-3); prn('Cengel 17-135 exit area (cm2)', 5.84, AeH, 2e-3, 'ours 5.845-5.846; printed 5.84 (0.1 %)')
